[Write file: site.js]
/* CS 101 — shared site behaviour.
   Plain script, no build step, no dependencies. Loaded on every page. */
(function () {
  'use strict';

  /* ---------- tiny helpers shared with the page renderers ---------- */

  function esc(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function el(html) {
    var tpl = document.createElement('template');
    tpl.innerHTML = String(html).trim();
    return tpl.content;
  }

  /* ---------- mobile navigation ---------- */

  function initNav() {
    var toggle = document.querySelector('.nav-toggle');
    var nav = document.getElementById('site-nav');
    if (!toggle || !nav) return;

    function setOpen(open) {
      nav.classList.toggle('is-open', open);
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    }

    toggle.addEventListener('click', function () {
      setOpen(toggle.getAttribute('aria-expanded') !== 'true');
    });

    // Following a link or hitting Escape closes the menu again.
    nav.addEventListener('click', function (event) {
      if (event.target.closest('a')) setOpen(false);
    });
    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && nav.classList.contains('is-open')) {
        setOpen(false);
        toggle.focus();
      }
    });
    // If the viewport grows past the breakpoint, drop the mobile state so the
    // desktop nav is never left in a stale "closed" style.
    window.addEventListener('resize', function () {
      if (window.innerWidth >= 768) setOpen(false);
    });
  }

  /* ---------- copy-to-clipboard buttons ---------- */

  function copyText(text) {
    if (navigator.clipboard && window.isSecureContext) {
      return navigator.clipboard.writeText(text);
    }
    // Fallback for file:// and plain http, where the async clipboard API is
    // unavailable. Students often open these pages straight off disk.
    return new Promise(function (resolve, reject) {
      var area = document.createElement('textarea');
      area.value = text;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.top = '-1000px';
      document.body.appendChild(area);
      area.select();
      var ok = false;
      try { ok = document.execCommand('copy'); } catch (err) { ok = false; }
      document.body.removeChild(area);
      ok ? resolve() : reject(new Error('copy failed'));
    });
  }

  function copyable(root) {
    var scope = root || document;
    var buttons = scope.querySelectorAll('.copy-btn[data-copy-target]');
    Array.prototype.forEach.call(buttons, function (btn) {
      if (btn.dataset.copyWired === 'true') return;
      btn.dataset.copyWired = 'true';
      var original = btn.textContent;
      btn.addEventListener('click', function () {
        var target = document.getElementById(btn.getAttribute('data-copy-target'));
        if (!target) return;
        copyText(target.textContent).then(function () {
          btn.textContent = 'Copied';
          btn.classList.add('is-copied');
        }, function () {
          btn.textContent = 'Press Ctrl+C';
          btn.classList.add('is-copied');
        });
        window.setTimeout(function () {
          btn.textContent = original;
          btn.classList.remove('is-copied');
        }, 1800);
      });
    });
  }

  /* ---------- boot ---------- */

  window.CS101 = { esc: esc, el: el, copyable: copyable };

  document.addEventListener('DOMContentLoaded', function () {
    initNav();
    copyable(document);
  });
})();

