[Write file: styles.css]
@charset "utf-8";

/* ============================================================================
   CS 101: Introduction to Computer Science — site stylesheet
   Fall 2026 · single file, no build step, no framework, no @import,
   no webfonts, no external URLs of any kind.

   Contents
     1.  Tokens (light palette + geometry + type)
     2.  Tokens (dark palette override — colour tokens only)
     3.  Reset & base elements
     4.  Accessibility utilities (skip link, focus, reduced motion)
     5.  Layout (.wrap, .section, .stack, grids)
     6.  Header, brand & navigation
     7.  Page head, hero & typography helpers
     8.  Cards
     9.  Callouts
     10. Badges
     11. Buttons & filter bar
     12. Tables
     13. Code blocks
     14. Definition grid (.dl-grid)
     15. Schedule weeks
     16. Assignments
     17. Contact
     18. Empty state
     19. Footer
     20. Print
   ==========================================================================*/


/* ============================================================================
   1. TOKENS — light palette (the default, defined on bare :root)
   ----------------------------------------------------------------------------
   Contrast intent (WCAG, ratios measured against the surface each value is
   actually painted on):
     --text        #1b1d24 on --surface #ffffff  ≈ 16.1:1   (body copy)
     --text        #1b1d24 on --bg      #f6f7fb  ≈ 15.1:1
     --text-muted  #555b6b on --surface #ffffff  ≈  6.9:1   (still > 4.5:1 so
                   muted text is never a contrast trap)
     --accent      #4338ca on --surface #ffffff  ≈  8.3:1   (links, large text)
     --accent-contrast #ffffff on --accent       ≈  8.3:1   (button labels)
     --ok          #146c3a on #ffffff            ≈  5.6:1
     --warn        #8a5300 on #ffffff            ≈  5.9:1
     --danger      #b42318 on #ffffff            ≈  5.9:1
     --border      #8c92a3 on #ffffff            ≈  3.1:1   (>= 3:1, used for
                   control outlines, table rules and any border that carries
                   meaning — i.e. real UI boundaries)
     --border-subtle is decorative only (hairline separators inside an already
                   bounded surface); it never carries information on its own,
                   so the 3:1 UI rule does not apply to it.
   ==========================================================================*/

:root {
  /* -- surfaces ------------------------------------------------------------ */
  --bg: #f6f7fb;             /* page canvas: a barely-there cool grey        */
  --surface: #ffffff;        /* cards, header, code blocks                   */
  --surface-2: #eceff6;      /* inset strips: code heads, table headers      */

  /* -- ink ----------------------------------------------------------------- */
  --text: #1b1d24;
  --text-muted: #555b6b;

  /* -- lines --------------------------------------------------------------- */
  --border: #8c92a3;         /* >= 3:1 — real UI boundaries                   */
  --border-subtle: #dfe3ec;  /* decorative hairlines inside a bounded surface */

  /* -- accent (single indigo, used sparingly) ------------------------------ */
  --accent: #4338ca;
  --accent-contrast: #ffffff;
  --accent-soft: #ecebff;    /* tinted fill behind accent content            */

  /* -- status -------------------------------------------------------------- */
  --ok: #146c3a;
  --ok-soft: #e6f5ec;
  --warn: #8a5300;
  --warn-soft: #fdf1de;
  --danger: #b42318;
  --danger-soft: #fdecea;

  /* -- geometry ------------------------------------------------------------ */
  --radius: 0.625rem;
  --radius-sm: 0.375rem;
  --radius-pill: 999px;
  --shadow: 0 1px 2px rgba(20, 24, 40, 0.06),
            0 6px 20px -12px rgba(20, 24, 40, 0.28);
  --shadow-sm: 0 1px 2px rgba(20, 24, 40, 0.08);

  /* -- type (system stacks only) ------------------------------------------ */
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue",
          Arial, "Noto Sans", sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas,
          "Liberation Mono", "Courier New", monospace;

  /* -- rhythm -------------------------------------------------------------- */
  --measure: 65ch;           /* comfortable reading width for prose          */
  --wrap: 68rem;
  --gap: 1.25rem;
  --space-section: 3rem;

  /* -- print ink (referenced only from the print block) -------------------- */
  --print-ink: #000000;
  --print-paper: #ffffff;
}


/* ============================================================================
   2. TOKENS — dark palette
   ----------------------------------------------------------------------------
   Only colour tokens are overridden; geometry and type stay identical.
   Contrast intent:
     --text        #e7e9f2 on --surface #171a22  ≈ 13.7:1
     --text-muted  #a6accd? -> #a7adc0 on #171a22 ≈  7.6:1
     --accent      #a9b6ff on #171a22            ≈  9.0:1  (light indigo keeps
                   the same "single accent" identity without glowing)
     --accent-contrast #101320 on --accent       ≈  9.0:1
     --ok          #4ade80 on #171a22            ≈ 10.2:1
     --warn        #f5b73d on #171a22            ≈  9.7:1
     --danger      #ff9c94 on #171a22            ≈  8.1:1
     --border      #5a6178 on #171a22            ≈  3.2:1  (>= 3:1)
   ==========================================================================*/

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0e1016;
    --surface: #171a22;
    --surface-2: #1f232e;

    --text: #e7e9f2;
    --text-muted: #a7adc0;

    --border: #5a6178;
    --border-subtle: #2b303d;

    --accent: #a9b6ff;
    --accent-contrast: #101320;
    --accent-soft: #232741;

    --ok: #4ade80;
    --ok-soft: #14291d;
    --warn: #f5b73d;
    --warn-soft: #2e2412;
    --danger: #ff9c94;
    --danger-soft: #331a18;

    --shadow: 0 1px 2px rgba(0, 0, 0, 0.5),
              0 8px 24px -14px rgba(0, 0, 0, 0.8);
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.5);
  }
}


/* ============================================================================
   3. RESET & BASE
   ==========================================================================*/

*,
*::before,
*::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: 5rem;   /* sticky header must not cover #anchors */
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.65;
  /* Nothing may ever push the page sideways — wide content scrolls inside
     .table-wrap / pre instead. */
  overflow-x: hidden;
  overflow-wrap: break-word;
  word-break: normal;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, h4, h5, h6 {
  margin: 0 0 0.5em;
  line-height: 1.2;
  font-weight: 650;
  letter-spacing: -0.01em;
  text-wrap: balance;
}

h1 { font-size: clamp(1.75rem, 1.35rem + 2vw, 2.5rem); }
h2 { font-size: clamp(1.35rem, 1.15rem + 1vw, 1.75rem); }
h3 { font-size: 1.15rem; }
h4 { font-size: 1rem; }

p, ul, ol, dl, figure, blockquote, table { margin: 0 0 1rem; }
p:last-child, ul:last-child, ol:last-child, dl:last-child { margin-bottom: 0; }

/* Comfortable measure for running prose. Grid/flex children inherit a
   narrower box anyway, so this only ever tightens, never overflows. */
main p,
main li,
main dd,
main blockquote { max-width: var(--measure); }

ul, ol { padding-left: 1.35rem; }
li + li { margin-top: 0.25rem; }

a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 0.15em;
  text-decoration-thickness: from-font;
  /* Long URLs must never widen the page. */
  overflow-wrap: anywhere;
}
a:hover { text-decoration-thickness: 2px; }

strong, b { font-weight: 650; }

hr {
  border: 0;
  border-top: 1px solid var(--border-subtle);
  margin: 2rem 0;
}

img, svg, video, canvas, iframe {
  max-width: 100%;
  height: auto;
  display: block;
}

blockquote {
  margin-inline: 0;
  padding: 0.25rem 0 0.25rem 1rem;
  border-left: 3px solid var(--border);
  color: var(--text-muted);
}

/* Inline code (block-level code is handled in §13). */
code, kbd, samp {
  font-family: var(--mono);
  font-size: 0.9em;
}

:not(pre) > code {
  background: var(--surface-2);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  padding: 0.1em 0.35em;
  overflow-wrap: anywhere;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}

::selection {
  background: var(--accent);
  color: var(--accent-contrast);
}


/* ============================================================================
   4. ACCESSIBILITY UTILITIES
   ==========================================================================*/

/* Skip link: off-screen but focusable, then pinned top-left when focused. */
.skip-link {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 100;
  transform: translateY(-150%);
  margin: 0.5rem;
  padding: 0.6rem 1rem;
  background: var(--accent);
  color: var(--accent-contrast);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
  text-decoration: none;
  font-weight: 600;
}

.skip-link:focus,
.skip-link:focus-visible {
  transform: translateY(0);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* One visible focus treatment for the whole site. Nothing anywhere in this
   file removes an outline without providing a replacement. */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

/* Browsers that support :focus-visible get the refined behaviour; the default
   focus ring is kept for everything else. */
:is(a, button, input, select, textarea, summary, [tabindex]):focus:not(:focus-visible) {
  outline: none;
}

#main:focus { outline: none; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}


/* ============================================================================
   5. LAYOUT
   ==========================================================================*/

.wrap {
  width: 100%;
  max-width: var(--wrap);
  margin-inline: auto;
  padding-inline: 1.125rem;
}

@media (min-width: 48rem) {
  .wrap { padding-inline: 2rem; }
}

.section {
  padding-block: 2.25rem;
}

@media (min-width: 48rem) {
  .section { padding-block: var(--space-section); }
}

.section + .section { padding-top: 0; }

/* Vertical flow: consistent gap between siblings without margin collapse. */
.stack > * + * { margin-top: var(--gap); }
.stack--tight > * + * { margin-top: 0.5rem; }

/* Card grids. auto-fit + minmax(min(100%, N)) collapses to a single column on
   narrow screens without needing a breakpoint, and never overflows at 320px. */
.grid {
  display: grid;
  gap: var(--gap);
  align-items: start;
}

.grid-2 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr)); }
.grid-3 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); }

/* Belt and braces: force one column below 40rem as the spec requires. */
@media (max-width: 39.999rem) {
  .grid-2,
  .grid-3 { grid-template-columns: 1fr; }
}


/* ============================================================================
   6. HEADER, BRAND & NAVIGATION
   ==========================================================================*/

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--surface);
  border-bottom: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-block: 0.75rem;
}

/* -- brand ---------------------------------------------------------------- */

.brand {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.5rem;
  text-decoration: none;
  color: var(--text);
  min-width: 0;
}

.brand:hover .brand-name { color: var(--text); }

.brand-code {
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--accent);
  font-size: 1.0625rem;
}

.brand-name {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* Keep the header compact on the very smallest screens. */
@media (max-width: 26.25rem) {
  .brand-name { display: none; }
}

/* -- toggle (mobile only) -------------------------------------------------- */

.nav-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.45rem 0.7rem;
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.nav-toggle:hover { background: var(--surface-2); }

.nav-toggle-label {
  font-size: 0.875rem;
  font-weight: 600;
}

/* Three bars drawn with currentColor, so they follow the token palette. */
.nav-toggle-bars {
  position: relative;
  display: block;
  width: 1.125rem;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
}

.nav-toggle-bars::before,
.nav-toggle-bars::after {
  content: "";
  position: absolute;
  left: 0;
  width: 100%;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
}

.nav-toggle-bars::before { top: -0.3125rem; }
.nav-toggle-bars::after { top: 0.3125rem; }

.nav-toggle[aria-expanded="true"] {
  background: var(--accent-soft);
  border-color: var(--accent);
}

/* -- nav ------------------------------------------------------------------- */

.site-nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.site-nav li + li { margin-top: 0; }

.site-nav a {
  display: block;
  padding: 0.6rem 0.5rem;
  border-radius: var(--radius-sm);
  color: var(--text);
  text-decoration: none;
  font-weight: 500;
}

.site-nav a:hover {
  background: var(--surface-2);
  color: var(--accent);
}

/* Current page is marked by weight + a solid underline rule, not colour
   alone, so it survives greyscale, dark mode and colour-blind viewing. */
.site-nav a[aria-current="page"] {
  color: var(--accent);
  font-weight: 700;
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 0.3em;
}

/* Mobile: hidden until .is-open, then a full-width stack under the header. */
@media (max-width: 47.999rem) {
  .site-nav {
    display: none;
    flex-basis: 100%;
    width: 100%;
  }

  .site-nav.is-open {
    display: block;
    border-top: 1px solid var(--border-subtle);
    padding-block: 0.5rem 0.75rem;
    margin-top: 0.25rem;
  }

  .site-nav.is-open a { padding-inline: 0.75rem; }

  .site-nav.is-open a[aria-current="page"] {
    background: var(--accent-soft);
  }
}

/* Desktop: horizontal row, no toggle. */
@media (min-width: 48rem) {
  .nav-toggle { display: none; }

  .site-nav {
    display: block;
    flex-basis: auto;
    width: auto;
  }

  .site-nav ul {
    flex-direction: row;
    align-items: center;
    gap: 0.25rem;
  }

  .site-nav a { padding: 0.4rem 0.7rem; }
}


/* ============================================================================
   7. PAGE HEAD, HERO & TYPOGRAPHY HELPERS
   ==========================================================================*/

.page-head {
  background: var(--surface);
  border-bottom: 1px solid var(--border-subtle);
  padding-block: 2rem 1.75rem;
  margin-bottom: 2rem;
}

.page-head h1 { margin-bottom: 0.35rem; }

.eyebrow {
  margin: 0 0 0.35rem;
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent);
}

.lede {
  font-size: 1.0625rem;
  line-height: 1.6;
  color: var(--text-muted);
  max-width: var(--measure);
}

@media (min-width: 48rem) {
  .lede { font-size: 1.15rem; }
}

.muted {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* -- hero (home page) ------------------------------------------------------ */

.hero {
  background: var(--surface);
  border-bottom: 1px solid var(--border-subtle);
  padding-block: 2.5rem 2.25rem;
}

@media (min-width: 48rem) {
  .hero { padding-block: 4rem 3.5rem; }
}

.hero h1 { max-width: 20ch; }
.hero .lede { max-width: 60ch; }

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}


/* ============================================================================
   8. CARDS
   ==========================================================================*/

.card {
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  padding: 1.25rem;
  height: 100%;
}

@media (min-width: 48rem) {
  .card { padding: 1.5rem; }
}

.card > :first-child { margin-top: 0; }
.card > :last-child { margin-bottom: 0; }

.card h2 {
  font-size: 1.25rem;
  margin-bottom: 0.4rem;
}

.card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.35rem;
}

.card-title {
  margin: 0 0 0.35rem;
  font-size: 1.125rem;
  font-weight: 650;
  line-height: 1.3;
}

.card-meta {
  margin: 0 0 0.75rem;
  font-size: 0.875rem;
  color: var(--text-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}


/* ============================================================================
   9. CALLOUTS
   ==========================================================================*/

.callout {
  border: 1px solid var(--border);
  border-left: 4px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  padding: 1rem 1.125rem;
  margin-block: 1.25rem;
}

.callout > :first-child { margin-top: 0; }
.callout > :last-child { margin-bottom: 0; }

.callout h2,
.callout h3,
.callout h4 {
  font-size: 1rem;
  margin-bottom: 0.35rem;
}

.callout-info {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.callout-warn {
  border-color: var(--warn);
  background: var(--warn-soft);
}

.callout-ok {
  border-color: var(--ok);
  background: var(--ok-soft);
}


/* ============================================================================
   10. BADGES
   ----------------------------------------------------------------------------
   Every badge pairs a tinted fill with a >= 4.5:1 label and a 3:1 border, so
   the meaning survives greyscale printing too.
   ==========================================================================*/

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.15rem 0.55rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--surface-2);
  color: var(--text);
  font-size: 0.78125rem;
  font-weight: 650;
  line-height: 1.5;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.badge-due {
  color: var(--warn);
  background: var(--warn-soft);
  border-color: var(--warn);
}

.badge-done {
  color: var(--ok);
  background: var(--ok-soft);
  border-color: var(--ok);
}

.badge-exam {
  color: var(--danger);
  background: var(--danger-soft);
  border-color: var(--danger);
}

.badge-holiday {
  color: var(--accent);
  background: var(--accent-soft);
  border-color: var(--accent);
}


/* ============================================================================
   11. BUTTONS & FILTER BAR
   ==========================================================================*/

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 2.75rem;          /* comfortable touch target */
  padding: 0.55rem 1.1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.3;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease,
              color 150ms ease, box-shadow 150ms ease;
}

.btn:hover {
  background: var(--surface-2);
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-contrast);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-contrast);
  box-shadow: var(--shadow);
}

.btn-ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--accent);
}

.btn-ghost:hover {
  background: var(--accent-soft);
  border-color: var(--accent);
}

/* -- filter bar (assignments + schedule) ---------------------------------- */

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.filter-btn {
  padding: 0.4rem 0.85rem;
  min-height: 2.25rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--surface);
  color: var(--text);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease,
              border-color 150ms ease;
}

.filter-btn:hover { background: var(--surface-2); }

/* Selected state marked by fill + weight, not colour alone. */
.filter-btn[aria-pressed="true"],
.filter-btn.is-active {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-contrast);
  font-weight: 700;
}


/* ============================================================================
   12. TABLES
   ==========================================================================*/

.table-wrap {
  overflow-x: auto;            /* wide tables scroll inside themselves */
  -webkit-overflow-scrolling: touch;
  max-width: 100%;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  margin-block: 1.25rem;
}

.data-table {
  width: 100%;
  min-width: 34rem;            /* below this the wrapper scrolls */
  margin: 0;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.data-table caption {
  caption-side: top;
  text-align: left;
  padding: 0.75rem 0.875rem;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.data-table th,
.data-table td {
  padding: 0.65rem 0.875rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--border-subtle);
}

.data-table thead th {
  position: sticky;
  top: 0;
  background: var(--surface-2);
  color: var(--text);
  font-weight: 700;
  font-size: 0.8125rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}

.data-table tbody tr:last-child th,
.data-table tbody tr:last-child td { border-bottom: 0; }

.data-table tbody tr:hover { background: var(--surface-2); }

.data-table td p { max-width: none; }


/* ============================================================================
   13. CODE BLOCKS
   ==========================================================================*/

.code-block {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;            /* clips the child corners to the radius */
  margin-block: 1.25rem;
}

.code-head {
  display: flex;
  align-items: center;
  justify-content: space-between;   /* .code-lang left, .copy-btn right */
  gap: 0.75rem;
  padding: 0.4rem 0.4rem 0.4rem 0.875rem;
  background: var(--surface-2);
  border-bottom: 1px solid var(--border);
}

.code-lang {
  font-family: var(--mono);
  font-size: 0.78125rem;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.copy-btn {
  flex: none;
  padding: 0.3rem 0.7rem;
  min-height: 2rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease,
              border-color 150ms ease;
}

.copy-btn:hover { background: var(--surface-2); }

/* Success state after CS101.copyable() copies (also used for the
   "Press Ctrl+C" fallback message, which is why it stays readable). */
.copy-btn.is-copied {
  background: var(--ok-soft);
  border-color: var(--ok);
  color: var(--ok);
}

.code-block pre {
  margin: 0;
  padding: 0.875rem 1rem;
  background: var(--surface);
}

pre {
  overflow-x: auto;            /* code scrolls inside its own box */
  -webkit-overflow-scrolling: touch;
  max-width: 100%;
  background: var(--surface);
  border-radius: var(--radius);
  margin-block: 1.25rem;
  padding: 0.875rem 1rem;
}

pre > code {
  display: block;
  font-family: var(--mono);
  font-size: 0.9rem;
  line-height: 1.6;
  tab-size: 4;
  -moz-tab-size: 4;
  color: var(--text);
  background: none;
  border: 0;
  padding: 0;
  /* Code must NOT wrap — it scrolls horizontally instead. */
  white-space: pre;
  overflow-wrap: normal;
  word-break: normal;
  min-width: max-content;
}


/* ============================================================================
   14. DEFINITION GRID
   ==========================================================================*/

.dl-grid {
  margin: 0;
  display: grid;
  grid-template-columns: 1fr;   /* mobile: stacked */
  gap: 0.25rem 1.25rem;
}

.dl-grid dt {
  font-weight: 650;
  color: var(--text);
}

.dl-grid dd {
  margin: 0 0 0.75rem;
  color: var(--text-muted);
  max-width: var(--measure);
}

.dl-grid dd:last-child { margin-bottom: 0; }

@media (min-width: 40rem) {
  .dl-grid {
    grid-template-columns: minmax(8rem, 14rem) minmax(0, 1fr);
    row-gap: 0.75rem;
  }

  .dl-grid dt {
    grid-column: 1;
    padding-top: 0.05rem;
  }

  .dl-grid dd {
    grid-column: 2;
    margin-bottom: 0;
  }

  /* Hairline between rows keeps a long key/value list scannable. */
  .dl-grid dt + dd { border-bottom: 0; }
}


/* ============================================================================
   15. SCHEDULE WEEKS
   ==========================================================================*/

.week {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.35rem 1.25rem;
  padding: 1.125rem;
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}

.week + .week { margin-top: 0.875rem; }

.week-num {
  display: inline-flex;
  align-items: center;
  align-self: start;
  padding: 0.1rem 0.6rem;
  border: 1px solid var(--accent);
  border-radius: var(--radius-pill);
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 0.78125rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.week-dates {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.week-topic {
  margin: 0;
  font-size: 1.0625rem;
  font-weight: 650;
  line-height: 1.35;
  color: var(--text);
}

.week-readings,
.week-due {
  margin: 0;
  font-size: 0.9375rem;
  color: var(--text-muted);
  max-width: var(--measure);
}

.week-readings strong,
.week-due strong { color: var(--text); }

.week-due { color: var(--text); }

@media (min-width: 48rem) {
  /* Two columns: a narrow "when" rail, then the content. */
  .week {
    grid-template-columns: 8.5rem minmax(0, 1fr);
    padding: 1.25rem 1.5rem;
  }

  .week-num,
  .week-dates { grid-column: 1; }

  .week-topic,
  .week-readings,
  .week-due { grid-column: 2; }

  .week-topic { grid-row: 1; }
  .week-num { grid-row: 1; }
  .week-dates { grid-row: 2; }
}


/* ============================================================================
   16. ASSIGNMENTS
   ==========================================================================*/

.assignment {
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.assignment + .assignment { margin-top: 1rem; }

.assignment-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem 0.875rem;
  padding: 0.9rem 1.125rem;
  background: var(--surface-2);
  border-bottom: 1px solid var(--border-subtle);
}

.assignment-head h2,
.assignment-head h3,
.assignment-head .card-title {
  margin: 0;
  font-size: 1.0625rem;
}

.assignment-body {
  padding: 1.125rem;
}

.assignment-body > :first-child { margin-top: 0; }
.assignment-body > :last-child { margin-bottom: 0; }

@media (min-width: 48rem) {
  .assignment-head { padding: 1rem 1.5rem; }
  .assignment-body { padding: 1.5rem; }
}


/* ============================================================================
   17. CONTACT
   ==========================================================================*/

.contact-grid {
  display: grid;
  gap: var(--gap);
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
  align-items: start;
}

.contact-card {
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  border-left: 4px solid var(--accent);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  padding: 1.125rem 1.25rem;
  height: 100%;
}

.contact-card > :first-child { margin-top: 0; }
.contact-card > :last-child { margin-bottom: 0; }

.contact-card h2,
.contact-card h3 {
  font-size: 1.0625rem;
  margin-bottom: 0.35rem;
}

.contact-card a { overflow-wrap: anywhere; }


/* ============================================================================
   18. EMPTY STATE
   ==========================================================================*/

.empty {
  margin: 0;
  padding: 1.5rem 1.25rem;
  border: 1px dashed var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text-muted);
  text-align: center;
  font-size: 0.9375rem;
  max-width: none;
}


/* ============================================================================
   19. FOOTER
   ==========================================================================*/

.site-footer {
  margin-top: 3rem;
  background: var(--surface);
  border-top: 1px solid var(--border-subtle);
  padding-block: 1.75rem;
}

.footer-inner {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  justify-content: space-between;
  align-items: flex-start;
}

.footer-course {
  margin: 0 0 0.25rem;
  font-weight: 650;
}

.site-footer p { max-width: var(--measure); }

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.125rem;
}

.footer-nav a {
  color: var(--text-muted);
  font-size: 0.9375rem;
  text-decoration: none;
}

.footer-nav a:hover {
  color: var(--accent);
  text-decoration: underline;
}

@media (min-width: 48rem) {
  .footer-inner {
    flex-direction: row;
    align-items: center;
  }
}


/* ============================================================================
   20. PRINT — a clean black-on-white syllabus handout
   ==========================================================================*/

@media print {
  html, body {
    background: var(--print-paper);
    color: var(--print-ink);
    font-size: 11pt;
    line-height: 1.45;
  }

  /* Navigation chrome is meaningless on paper. */
  .site-header .site-nav,
  .site-header .nav-toggle,
  .nav-toggle,
  .footer-nav,
  .skip-link,
  .filter-bar,
  .copy-btn,
  .hero-actions { display: none !important; }

  .site-header {
    position: static;
    box-shadow: none;
    border-bottom: 1pt solid var(--print-ink);
    background: var(--print-paper);
  }

  .brand-code,
  .brand-name,
  .eyebrow,
  .lede,
  .muted,
  .week-dates,
  .week-readings,
  .card-meta,
  .code-lang,
  a { color: var(--print-ink); }

  a { text-decoration: underline; }

  /* Show link targets so a printed page is still navigable. */
  main a[href^="http"]::after,
  main a[href^="mailto:"]::after {
    content: " (" attr(href) ")";
    font-size: 0.85em;
    word-break: break-all;
  }

  .card,
  .callout,
  .week,
  .assignment,
  .contact-card,
  .code-block,
  .table-wrap,
  .empty,
  .page-head,
  .hero,
  .site-footer {
    background: var(--print-paper);
    color: var(--print-ink);
    border: 1pt solid var(--print-ink);
    box-shadow: none;
  }

  .page-head,
  .hero,
  .site-footer { border: 0; border-top: 1pt solid var(--print-ink); }
  .page-head, .hero { border: 0; border-bottom: 1pt solid var(--print-ink); }

  .badge,
  .week-num,
  .filter-btn {
    background: var(--print-paper);
    color: var(--print-ink);
    border: 1pt solid var(--print-ink);
  }

  .assignment-head,
  .code-head,
  .data-table thead th {
    background: var(--print-paper);
    color: var(--print-ink);
    border-bottom: 1pt solid var(--print-ink);
  }

  /* Code must be fully visible on paper: no scrollbars, so let it wrap. */
  .table-wrap { overflow: visible; }

  pre,
  .code-block pre {
    background: var(--print-paper);
    overflow: visible;
  }

  pre > code {
    color: var(--print-ink);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    min-width: 0;
    font-size: 9.5pt;
  }

  .data-table th,
  .data-table td {
    border-bottom: 0.5pt solid var(--print-ink);
    color: var(--print-ink);
  }

  .data-table { min-width: 0; }

  /* Keep blocks whole across page breaks where we reasonably can. */
  h1, h2, h3, h4 { break-after: avoid-page; }
  .card, .callout, .week, .assignment, .code-block, tr { break-inside: avoid; }

  @page { margin: 16mm; }
}

