/* CS 101 — schedule page renderer.
   Reads window.SCHEDULE (see data/schedule.js) and draws the week list.
   Plain script, no modules, no dependencies beyond the CS101 helpers.
   Instructors never need to edit this file — only data/schedule.js. */
(function () {
  'use strict';

  var esc = (window.CS101 && window.CS101.esc) || function (v) {
    return String(v == null ? '' : v)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  };

  var FILTERS = [
    { id: 'all', label: 'All weeks' },
    { id: 'upcoming', label: 'Upcoming' },
    { id: 'deadlines', label: 'Exams & deadlines' },
  ];

  var activeFilter = 'all';
  var weeksEl = null;
  var barEl = null;

  /* ---------- small helpers ---------- */

  function list(value) {
    return Object.prototype.toString.call(value) === '[object Array]' ? value : [];
  }

  function weekId(week, index) {
    var n = week.number;
    if (typeof n === 'number' && isFinite(n)) return 'week-' + n;
    if (typeof n === 'string' && n !== '') return 'week-' + n.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
    return 'week-break-' + (index + 1);
  }

  function weekLabel(week) {
    var n = week.number;
    if (n === null || n === undefined || n === '') return 'Break';
    return 'Week ' + n;
  }

  /* ---------- markup ---------- */

  function linkHtml(label, url, className) {
    // A link with no address is rendered as plain text rather than a dead <a>.
    var text = esc(label || 'Untitled');
    if (!url) return '<span' + (className ? ' class="' + className + '"' : '') + '>' + text + '</span>';
    return '<a href="' + esc(url) + '"' + (className ? ' class="' + className + '"' : '') +
      '>' + text + '</a>';
  }

  function badgeFor(week) {
    if (week.kind === 'exam') return '<span class="badge badge-exam">Exam</span>';
    if (week.kind === 'holiday') return '<span class="badge badge-holiday">No class</span>';
    if (week.kind === 'project') return '<span class="badge">Project</span>';
    return '';
  }

  function readingsHtml(week) {
    var readings = list(week.readings);
    if (!readings.length) return '';
    var items = readings.map(function (r) {
      return '<li>' + linkHtml(r && r.label, r && r.url) + '</li>';
    }).join('');
    return '<div class="week-readings">' +
      '<h3>Readings</h3><ul>' + items + '</ul></div>';
  }

  function dueHtml(week) {
    var due = list(week.due);
    if (!due.length) return '';
    var items = due.map(function (d) {
      return '<li>' + linkHtml(d && d.label, d && d.href, 'badge badge-due') + '</li>';
    }).join('');
    return '<div class="week-due">' +
      '<h3>Due this week</h3><ul>' + items + '</ul></div>';
  }

  function slidesHtml(week) {
    var s = week.slides;
    if (!s || !s.url) return '';
    return '<p>' + linkHtml(s.label || 'Slides', s.url) + '</p>';
  }

  function weekHtml(week, index) {
    var id = weekId(week, index);
    var current = week.status === 'current';
    var titleId = id + '-title';

    return '<article class="week' + (current ? ' is-current' : '') + '" id="' + esc(id) + '"' +
        ' aria-labelledby="' + esc(titleId) + '"' +
        ' data-status="' + esc(week.status || 'upcoming') + '"' +
        ' data-kind="' + esc(week.kind || 'regular') + '">' +
woo      '</article>';
  }

  /* ---------- rendering ---------- */

  function render() {
    var data = window.SCHEDULE;
    var weeks = data ? list(data.weeks) : [];

    if (!weeks.length) {
      weeksEl.innerHTML = '';
      weeksEl.appendChild(window.CS101.el(
        '<p class="empty">The schedule has not been posted yet. Check back soon, ' +
        'or see the syllabus for the term outline.</p>'
      ));
      if (barEl) barEl.hidden = true;
      return;
    }

    var html = weeks.map(weekHtml).join('') +
      '<p class="empty" id="schedule-empty" hidden>No weeks match that filter.</p>';
    weeksEl.innerHTML = '';
    weeksEl.appendChild(window.CS101.el(html));
    applyFilter();
  }

  function matches(el) {
    if (activeFilter === 'all') return true;
    if (activeFilter === 'upcoming') {
      var status = el.getAttribute('data-status');
      return status === 'current' || status === 'upcoming';
    }
    // "Exams & deadlines": exam weeks, plus any week with something due.
    return el.getAttribute('data-kind') === 'exam' || !!el.querySelector('.week-due');
  }

  function applyFilter() {
    var items = weeksEl.querySelectorAll('.week');
    var shown = 0;
    Array.prototype.forEach.call(items, function (el) {
      var ok = matches(el);
      el.hidden = !ok;
      if (ok) shown++;
    });

    var empty = document.getElementById('schedule-empty');
    if (empty) empty.hidden = shown !== 0;

    if (barEl) {
      Array.prototype.forEach.call(barEl.querySelectorAll('.filter-btn'), function (btn) {
        btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === activeFilter ? 'true' : 'false');
      });
    }
  }

  function buildFilterBar() {
    if (!barEl) return;
    barEl.innerHTML = '';
    barEl.appendChild(window.CS101.el(FILTERS.map(function (f) {
      return '<button type="button" class="filter-btn" data-filter="' + esc(f.id) + '"' +
        ' aria-pressed="' + (f.id === activeFilter ? 'true' : 'false') + '">' +
        esc(f.label) + '</button>';
    }).join('')));

    barEl.addEventListener('click', function (event) {
      var btn = event.target.closest ? event.target.closest('.filter-btn') : null;
      if (!btn) return;
      activeFilter = btn.getAttribute('data-filter') || 'all';
      applyFilter();
    });
  }

  /* ---------- deep links (schedule.html#week-3) ---------- */

  function focusHashTarget() {
    var hash = window.location.hash;
    if (!/^#week-[a-z0-9-]+$/i.test(hash)) return;
    var target = document.getElementById(hash.slice(1));
    if (!target) return;
    // A filter must never hide the week someone linked to.
    if (activeFilter !== 'all') {
      activeFilter = 'all';
      applyFilter();
    }
    target.scrollIntoView();
  }

  document.addEventListener('DOMContentLoaded', function () {
    weeksEl = document.getElementById('schedule-weeks');
    barEl = document.getElementById('schedule-filters');
    if (!weeksEl) return;
    buildFilterBar();
    render();
    focusHashTarget();
    window.addEventListener('hashchange', focusHashTarget);
  });
})();

