/* CS 101 — assignments page renderer.
   Reads window.ASSIGNMENTS (see data/assignments.js) and builds the list.
   Plain script, no modules, no dependencies beyond the CS101 helpers in
   assets/site.js. Every value that comes out of the data file is escaped
   with CS101.esc before it reaches the page. */
(function () {
  'use strict';

  var CS101 = window.CS101 || {};
  var esc = CS101.esc || function (value) { return String(value == null ? '' : value); };

  var TYPE_LABELS = { ps: 'Problem set', lab: 'Lab', project: 'Project' };
  var STATUS_LABELS = { open: 'Open', closed: 'Closed', upcoming: 'Upcoming' };

  var FILTERS = [
    { key: 'all', label: 'All' },
    { key: 'ps', label: 'Problem sets' },
    { key: 'lab', label: 'Labs' },
    { key: 'project', label: 'Project' }
  ];

  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  /* ---------- small helpers ---------- */

  // "2026-09-04" -> "Fri 4 Sep 2026". Parsed by hand so the browser's
  // timezone can never shift the date by a day.
  function formatDate(value) {
    var text = String(value == null ? '' : value).trim();
    var parts = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
    if (!parts) return text;
    var year = Number(parts[1]);
    var month = Number(parts[2]) - 1;
    var day = Number(parts[3]);
    if (month < 0 || month > 11) return text;
    var date = new Date(Date.UTC(year, month, day));
    return DAYS[date.getUTCDay()] + ' ' + day + ' ' + MONTHS[month] + ' ' + year;
  }

  function list(value) {
    return Object.prototype.toString.call(value) === '[object Array]' ? value : [];
  }

  function typeLabel(type) {
    return TYPE_LABELS[type] || 'Assignment';
  }

  /* ---------- code blocks ---------- */

  // Matches the site's code-block contract exactly. `id` must be unique on
  // the page; the Copy button finds its <code> through data-copy-target.
  function codeBlock(id, lang, code) {
    var body = String(code == null ? '' : code).replace(/^\n+/, '').replace(/\s+$/, '');
    return '' +
      '<div class="code-block">' +
        '<div class="code-head">' +
          '<span class="code-lang">' + esc(lang || 'Python') + '</span>' +
          '<button class="copy-btn" data-copy-target="' + esc(id) + '">Copy</button>' +
        '</div>' +
        '<pre><code id="' + esc(id) + '">' + esc(body) + '</code></pre>' +
      '</div>';
  }

  /* ---------- one assignment ---------- */

  function renderItem(item) {
    var id = String(item.id == null ? '' : item.id);
    var type = String(item.type == null ? '' : item.type);
    var status = String(item.status == null ? '' : item.status);
    var html = [];

    html.push('<article class="assignment" id="' + esc(id) + '" data-type="' + esc(type) + '">');

    /* --- head --- */
    html.push('<div class="assignment-head">');
    html.push('<p><span class="badge">' + esc(typeLabel(type)) + '</span> ' +
              '<span class="badge badge-due">Due ' + esc(formatDate(item.due)) + '</span></p>');
    html.push('<h2 class="card-title">' + esc(item.title) + '</h2>');
    html.push('<p class="card-meta">' +
              esc(item.points) + ' points · Posted ' + esc(formatDate(item.posted)) +
              ' · Week ' + esc(item.week) +
              ' · ' + esc(STATUS_LABELS[status] || status) +
              '</p>');
    html.push('</div>');

    /* --- body --- */
    html.push('<div class="assignment-body">');

    if (item.summary) {
      html.push('<p class="lede">' + esc(item.summary) + '</p>');
    }

    var objectives = list(item.objectives);
    if (objectives.length) {
      html.push('<h3>What you will practise</h3><ul>');
      objectives.forEach(function (line) {
        html.push('<li>' + esc(line) + '</li>');
      });
      html.push('</ul>');
    }

    var tasks = list(item.tasks);
    if (tasks.length) {
      html.push('<h3>What to do</h3><ol>');
      tasks.forEach(function (line) {
        html.push('<li>' + esc(line) + '</li>');
      });
      html.push('</ol>');
    }

    if (item.starter && item.starter.code) {
      html.push('<h3>Starter file</h3>');
      html.push('<p class="muted">Save this as <code>' + esc(item.starter.filename || 'starter.py') +
                '</code>, then work through the TODO comments.</p>');
      html.push(codeBlock('code-' + id + '-starter', item.starter.lang, item.starter.code));
    }

    var examples = list(item.examples);
    if (examples.length) {
      html.push('<h3>Worked example' + (examples.length > 1 ? 's' : '') + '</h3>');
      examples.forEach(function (example, index) {
        html.push('<p class="card-title">' + esc(example.title) + '</p>');
        if (example.note) {
          html.push('<div class="callout callout-info"><p>' + esc(example.note) + '</p></div>');
        }
        html.push(codeBlock('code-' + id + '-ex' + (index + 1), example.lang, example.code));
      });
    }

    if (item.submit) {
      html.push('<h3>How to hand it in</h3>');
      html.push('<div class="callout callout-ok"><p>' + esc(item.submit) + '</p></div>');
    }

    var rubric = list(item.rubric);
    if (rubric.length) {
      var total = 0;
      html.push('<h3>Marking</h3>');
      html.push('<div class="table-wrap"><table class="data-table">');
      html.push('<caption class="muted">Rubric for ' + esc(item.title) + '</caption>');
      html.push('<thead><tr><th scope="col">Criterion</th><th scope="col">Points</th></tr></thead>');
      html.push('<tbody>');
      rubric.forEach(function (row) {
        total += Number(row && row.points) || 0;
        html.push('<tr><td>' + esc(row && row.criterion) + '</td><td>' + esc(row && row.points) + '</td></tr>');
      });
      html.push('</tbody>');
      html.push('<tfoot><tr><th scope="row">Total</th><td>' + esc(total) + '</td></tr></tfoot>');
      html.push('</table></div>');
    }

    html.push('</div>');   // .assignment-body
    html.push('</article>');

    return html.join('');
  }

  /* ---------- page wiring ---------- */

  function init() {
    var listNode = document.getElementById('assignment-list');
    var filterNode = document.getElementById('assignment-filters');
    if (!listNode) return;

    var data = window.ASSIGNMENTS;
    var items = data && list(data.items).filter(function (item) {
      return item && item.id;
    });

    if (!items || !items.length) {
      listNode.innerHTML = '<p class="empty">No assignments have been posted yet. ' +
        'Check back after the first lecture.</p>';
      if (filterNode) filterNode.innerHTML = '';
      return;
    }

    // Build the filter bar from FILTERS so the markup and the behaviour
    // can never drift apart.
    if (filterNode) {
      var bar = ['<div class="filter-bar" role="group" aria-label="Filter assignments">'];
      FILTERS.forEach(function (filter) {
        bar.push('<button type="button" class="filter-btn" data-filter="' + filter.key +
                 '" aria-pressed="' + (filter.key === 'all' ? 'true' : 'false') + '">' +
                 filter.label + '</button>');
      });
      bar.push('</div>');
      filterNode.innerHTML = bar.join('');
    }

    var body = items.map(renderItem).join('');
    listNode.innerHTML = body + '<p class="empty" id="assignment-empty" hidden>' +
      'No assignments of that kind yet.</p>';

    // The copy buttons only exist now that the HTML has been injected.
    if (typeof CS101.copyable === 'function') CS101.copyable(listNode);

    var articles = listNode.querySelectorAll('.assignment');
    var emptyNote = document.getElementById('assignment-empty');
    var buttons = filterNode ? filterNode.querySelectorAll('.filter-btn') : [];

    function applyFilter(key) {
      var shown = 0;
      Array.prototype.forEach.call(articles, function (article) {
        var match = key === 'all' || article.getAttribute('data-type') === key;
        article.hidden = !match;
        if (match) shown += 1;
      });
      if (emptyNote) emptyNote.hidden = shown !== 0;
      Array.prototype.forEach.call(buttons, function (button) {
        button.setAttribute('aria-pressed',
          button.getAttribute('data-filter') === key ? 'true' : 'false');
      });
    }

    Array.prototype.forEach.call(buttons, function (button) {
      button.addEventListener('click', function () {
        applyFilter(button.getAttribute('data-filter'));
      });
    });

    applyFilter('all');

    // Deep links from the schedule page look like assignments.html#ps3.
    // Clear any filter first so the target is definitely visible, then scroll.
    function goToHash() {
      var wanted = decodeURIComponent(String(window.location.hash || '').replace(/^#/, ''));
      if (!wanted) return;
      var target = document.getElementById(wanted);
      if (!target || !target.classList.contains('assignment')) return;
      applyFilter('all');
      target.scrollIntoView();
    }

    goToHash();
    window.addEventListener('hashchange', goToHash);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

1	/* CS 101 — shared site behaviour.
2	   Plain script, no build step, no dependencies. Loaded on every page. */
3	(function () {
4	  'use strict';
5	
6	  /* ---------- tiny helpers shared with the page renderers ---------- */
7	
8	  function esc(value) {
9	    return String(value == null ? '' : value)
10	      .replace(/&/g, '&amp;')
11	      .replace(/</g, '&lt;')
12	      .replace(/>/g, '&gt;')
13	      .replace(/"/g, '&quot;')
14	      .replace(/'/g, '&#39;');
15	  }
16	
17	  function el(html) {
18	    var tpl = document.createElement('template');
19	    tpl.innerHTML = String(html).trim();
20	    return tpl.content;
21	  }
22	
23	  /* ---------- mobile navigation ---------- */
24	
25	  function initNav() {
26	    var toggle = document.querySelector('.nav-toggle');
27	    var nav = document.getElementById('site-nav');
28	    if (!toggle || !nav) return;
29	
30	    function setOpen(open) {
31	      nav.classList.toggle('is-open', open);
32	      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
33	    }
34	
35	    toggle.addEventListener('click', function () {
36	      setOpen(toggle.getAttribute('aria-expanded') !== 'true');
37	    });
38	
39	    // Following a link or hitting Escape closes the menu again.
40	    nav.addEventListener('click', function (event) {
41	      if (event.target.closest('a')) setOpen(false);
42	    });
43	    document.addEventListener('keydown', function (event) {
44	      if (event.key === 'Escape' && nav.classList.contains('is-open')) {
45	        setOpen(false);
46	        toggle.focus();
47	      }
48	    });
49	    // If the viewport grows past the breakpoint, drop the mobile state so the
50	    // desktop nav is never left in a stale "closed" style.
51	    window.addEventListener('resize', function () {
52	      if (window.innerWidth >= 768) setOpen(false);
53	    });
54	  }
55	
56	  /* ---------- copy-to-clipboard buttons ---------- */
57	
58	  function copyText(text) {
59	    if (navigator.clipboard && window.isSecureContext) {
60	      return navigator.clipboard.writeText(text);
61	    }
62	    // Fallback for file:// and plain http, where the async clipboard API is
63	    // unavailable. Students often open these pages straight off disk.
64	    return new Promise(function (resolve, reject) {
65	      var area = document.createElement('textarea');
66	      area.value = text;
67	      area.setAttribute('readonly', '');
68	      area.style.position = 'fixed';
69	      area.style.top = '-1000px';
70	      document.body.appendChild(area);
71	      area.select();
72	      var ok = false;
73	      try { ok = document.execCommand('copy'); } catch (err) { ok = false; }
74	      document.body.removeChild(area);
75	      ok ? resolve() : reject(new Error('copy failed'));
76	    });
77	  }
78	
79	  function copyable(root) {
80	    var scope = root || document;
81	    var buttons = scope.querySelectorAll('.copy-btn[data-copy-target]');
82	    Array.prototype.forEach.call(buttons, function (btn) {
83	      if (btn.dataset.copyWired === 'true') return;
84	      btn.dataset.copyWired = 'true';
85	      var original = btn.textContent;
86	      btn.addEventListener('click', function () {
87	        var target = document.getElementById(btn.getAttribute('data-copy-target'));
88	        if (!target) return;
89	        copyText(target.textContent).then(function () {
90	          btn.textContent = 'Copied';
91	          btn.classList.add('is-copied');
92	        }, function () {
93	          btn.textContent = 'Press Ctrl+C';
94	          btn.classList.add('is-copied');
95	        });
96	        window.setTimeout(function () {
97	          btn.textContent = original;
98	          btn.classList.remove('is-copied');
99	        }, 1800);
100	      });
101	    });
102	  }
103	
104	  /* ---------- boot ---------- */
105	
106	  window.CS101 = { esc: esc, el: el, copyable: copyable };
107	
108	  document.addEventListener('DOMContentLoaded', function () {
109	    initNav();
110	    copyable(document);
111	  });
112	})();
