171	
172	    if (!items || !items.length) {
173	      listNode.innerHTML = '<p class="empty">No assignments have been posted yet. ' +
174	        'Check back after the first lecture.</p>';
175	      if (filterNode) filterNode.innerHTML = '';
176	      return;
177	    }
178	
179	    // Build the filter bar from FILTERS so the markup and the behaviour
180	    // can never drift apart.
181	    if (filterNode) {
182	      var bar = ['<div class="filter-bar" role="group" aria-label="Filter assignments">'];
183	      FILTERS.forEach(function (filter) {
184	        bar.push('<button type="button" class="filter-btn" data-filter="' + filter.key +
185	                 '" aria-pressed="' + (filter.key === 'all' ? 'true' : 'false') + '">' +
186	                 filter.label + '</button>');
