199	    var articles = listNode.querySelectorAll('.assignment');
200	    var emptyNote = document.getElementById('assignment-empty');
201	    var buttons = filterNode ? filterNode.querySelectorAll('.filter-btn') : [];
202	
203	    function applyFilter(key) {
