2	   Reads window.SCHEDULE (see data/schedule.js) and draws the week list.
3	   Plain script, no modules, no dependencies beyond the CS101 helpers.
4	   Instructors never need to edit this file — only data/schedule.js. */
5	(function () {
6	  'use strict';
7	
8	  var esc = (window.CS101 && window.CS101.esc) || function (v) {
9	    return String(v == null ? '' : v)
10	      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
11	      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
12	  };
13	
14	  var el = (window.CS101 && window.CS101.el) || function (html) {
15	    var tpl = document.createElement('template');
16	    tpl.innerHTML = String(html).trim();
17	    return tpl.content;
18	  };
19	
20	  var FILTERS = [
21	    { id: 'all', label: 'All weeks' },
22	    { id: 'upcoming', label: 'Upcoming' },
23	    { id: 'deadlines', label: 'Exams & deadlines' },
24	  ];
25	
26	  var activeFilter = 'all';
27	  var weeksEl = null;
28	  var barEl = null;
29	
30	  /* ---------- small helpers ---------- */
31	
32	  function list(value) {
33	    return Object.prototype.toString.call(value) === '[object Array]' ? value : [];
34	  }
35	
36	  function weekId(week, index) {
37	    var n = week.number;
38	    if (typeof n === 'number' && isFinite(n)) return 'week-' + n;
39	    if (typeof n === 'string' && n !== '') return 'week-' + n.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
40	    return 'week-break-' + (index + 1);
41	  }
42	
43	  function weekLabel(week) {
44	    var n = week.number;
45	    if (n === null || n === undefined || n === '') return 'Break';
46	    return 'Week ' + n;
47	  }
48	
49	  /* ---------- markup ---------- */
50	
51	  function linkHtml(label, url, className) {
52	    // A link with no address is rendered as plain text rather than a dead <a>.
53	    var text = esc(label || 'Untitled');
54	    if (!url) return '<span' + (className ? ' class="' + className + '"' : '') + '>' + text + '</span>';
55	    return '<a href="' + esc(url) + '"' + (className ? ' class="' + className + '"' : '') +
56	      '>' + text + '</a>';
57	  }
58	
59	  function badgeFor(week) {
60	    if (week.kind === 'exam') return '<span class="badge badge-exam">Exam</span>';
61	    if (week.kind === 'holiday') return '<span class="badge badge-holiday">No class</span>';
62	    if (week.kind === 'project') return '<span class="badge">Project</span>';
63	    return '';
64	  }
65	
66	  function readingsHtml(week) {
67	    var readings = list(week.readings);
68	    if (!readings.length) return '';
69	    var items = readings.map(function (r) {
70	      return '<li>' + linkHtml(r && r.label, r && r.url) + '</li>';
71	    }).join('');
72	    return '<div class="week-readings">' +
73	      '<h3>Readings</h3><ul>' + items + '</ul></div>';
74	  }
75	
76	  function dueHtml(week) {
77	    var due = list(week.due);
78	    if (!due.length) return '';
79	    var items = due.map(function (d) {
80	      return '<li>' + linkHtml(d && d.label, d && d.href, 'badge badge-due') + '</li>';
81	    }).join('');
82	    return '<div class="week-due">' +
83	      '<h3>Due this week</h3><ul>' + items + '</ul></div>';
84	  }
85	
86	  function slidesHtml(week) {
87	    var s = week.slides;
88	    if (!s || !s.url) return '';
89	    return '<p>' + linkHtml(s.label || 'Slides', s.url) + '</p>';
90	  }
91	
92	  function weekHtml(week, index) {
93	    var id = weekId(week, index);
94	    var current = week.status === 'current';
95	    var titleId = id + '-title';
96	
97	    return '<article class="week' + (current ? ' is-current' : '') + '" id="' + esc(id) + '"' +
98	        ' aria-labelledby="' + esc(titleId) + '"' +
99	        ' data-status="' + esc(week.status || 'upcoming') + '"' +
100	        ' data-kind="' + esc(week.kind || 'regular') + '">' +
101	      '<p class="week-num">' + esc(weekLabel(week)) +
102	        (current ? ' <span class="badge">This week</span>' : '') + '</p>' +
103	      '<p class="week-dates">' + esc(week.dates || 'Dates to be announced') + '</p>' +
104	      '<h2 class="week-topic" id="' + esc(titleId) + '">' + esc(week.topic || 'Topic to be announced') +
105	        (badgeFor(week) ? ' ' + badgeFor(week) : '') + '</h2>' +
106	      (week.summary ? '<p class="muted">' + esc(week.summary) + '</p>' : '') +
107	      readingsHtml(week) +
108	      dueHtml(week) +
109	      slidesHtml(week) +
110	      '</article>';
111	  }
112	
113	  /* ---------- rendering ---------- */
114	
115	  var allWeeks = [];
116	
117	  function render() {
118	    var data = window.SCHEDULE;
119	    allWeeks = data ? list(data.weeks) : [];
120	
121	    if (!allWeeks.length) {
122	      weeksEl.innerHTML = '';
123	      weeksEl.appendChild(el(
124	        '<p class="empty">The schedule has not been posted yet. Check back soon, ' +
125	        'or see the syllabus for the term outline.</p>'
126	      ));
127	      if (barEl) barEl.innerHTML = '';
128	      return;
129	    }
130	    applyFilter();
131	  }
132	
133	  function matches(week) {
134	    if (activeFilter === 'all') return true;
135	    if (activeFilter === 'upcoming') {
136	      return week.status === 'current' || week.status === 'upcoming';
137	    }
138	    // "Exams & deadlines": exam weeks, plus any week with something due.
139	    return week.kind === 'exam' || list(week.due).length > 0;
140	  }
141	
142	  function applyFilter() {
143	    // Re-rendering (rather than hiding) keeps the visible list free of any
144	    // stale rows and needs no cooperation from the stylesheet.
145	    var html = allWeeks.map(function (week, index) {
146	      return matches(week) ? weekHtml(week, index) : '';
147	    }).join('');
148	
149	    if (!html) {
150	      html = '<p class="empty">No weeks match that filter. Choose ' +
151	        '&ldquo;All weeks&rdquo; to see the whole term.</p>';
152	    }
153	    weeksEl.innerHTML = '';
154	    weeksEl.appendChild(el(html));
155	
156	    if (barEl) {
157	      Array.prototype.forEach.call(barEl.querySelectorAll('.filter-btn'), function (btn) {
158	        btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === activeFilter ? 'true' : 'false');
159	      });
160	    }
161	  }
162	
163	  function buildFilterBar() {
164	    if (!barEl) return;
165	    barEl.innerHTML = '';
166	    barEl.appendChild(el(FILTERS.map(function (f) {
167	      return '<button type="button" class="filter-btn" data-filter="' + esc(f.id) + '"' +
168	        ' aria-pressed="' + (f.id === activeFilter ? 'true' : 'false') + '">' +
169	        esc(f.label) + '</button>';
170	    }).join('')));
171	
172	    barEl.addEventListener('click', function (event) {
173	      var btn = event.target.closest ? event.target.closest('.filter-btn') : null;
174	      if (!btn) return;
175	      activeFilter = btn.getAttribute('data-filter') || 'all';
176	      applyFilter();
177	    });
178	  }
179	
180	  /* ---------- deep links (schedule.html#week-3) ---------- */
181	
182	  function focusHashTarget() {
183	    var hash = window.location.hash;
184	    if (!/^#week-[a-z0-9-]+$/i.test(hash)) return;
185	    // A filter must never hide the week someone linked to, so clear it first
186	    // and only then look the target up (filtering re-creates the elements).
187	    if (activeFilter !== 'all') {
188	      activeFilter = 'all';
189	      applyFilter();
190	    }
191	    var target = document.getElementById(hash.slice(1));
192	    if (target) target.scrollIntoView();
193	  }
194	
195	  document.addEventListener('DOMContentLoaded', function () {
196	    weeksEl = document.getElementById('schedule-weeks');
197	    barEl = document.getElementById('schedule-filters');
198	    if (!weeksEl) return;
199	    buildFilterBar();
200	    render();
201	    focusHashTarget();
202	    window.addEventListener('hashchange', focusHashTarget);
203	  });
204	})();
