1	/* CS 101 — shared site behaviour.
2	   Plain script, no build step, no dependencies. Loaded on every page. */
3	(function () {
4	  'use strict';
5	
6	  /* ---------- tiny helpers shared with the page renderers ---------- */
7	
8	  function esc(value) {
9	    return String(value == null ? '' : value)
10	      .replace(/&/g, '&amp;')
11	      .replace(/</g, '&lt;')
12	      .replace(/>/g, '&gt;')
13	      .replace(/"/g, '&quot;')
14	      .replace(/'/g, '&#39;');
15	  }
16	
17	  function el(html) {
18	    var tpl = document.createElement('template');
19	    tpl.innerHTML = String(html).trim();
20	    return tpl.content;
21	  }
22	
23	  /* ---------- mobile navigation ---------- */
24	
25	  function initNav() {
26	    var toggle = document.querySelector('.nav-toggle');
27	    var nav = document.getElementById('site-nav');
28	    if (!toggle || !nav) return;
29	
30	    function setOpen(open) {
31	      nav.classList.toggle('is-open', open);
32	      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
33	    }
34	
35	    toggle.addEventListener('click', function () {
36	      setOpen(toggle.getAttribute('aria-expanded') !== 'true');
37	    });
38	
39	    // Following a link or hitting Escape closes the menu again.
40	    nav.addEventListener('click', function (event) {
41	      if (event.target.closest('a')) setOpen(false);
42	    });
43	    document.addEventListener('keydown', function (event) {
44	      if (event.key === 'Escape' && nav.classList.contains('is-open')) {
45	        setOpen(false);
46	        toggle.focus();
47	      }
48	    });
49	    // If the viewport grows past the breakpoint, drop the mobile state so the
50	    // desktop nav is never left in a stale "closed" style.
51	    window.addEventListener('resize', function () {
52	      if (window.innerWidth >= 768) setOpen(false);
53	    });
54	  }
55	
56	  /* ---------- copy-to-clipboard buttons ---------- */
57	
58	  function copyText(text) {
59	    if (navigator.clipboard && window.isSecureContext) {
60	      return navigator.clipboard.writeText(text);
61	    }
62	    // Fallback for file:// and plain http, where the async clipboard API is
63	    // unavailable. Students often open these pages straight off disk.
64	    return new Promise(function (resolve, reject) {
65	      var area = document.createElement('textarea');
66	      area.value = text;
67	      area.setAttribute('readonly', '');
68	      area.style.position = 'fixed';
69	      area.style.top = '-1000px';
70	      document.body.appendChild(area);
71	      area.select();
72	      var ok = false;
73	      try { ok = document.execCommand('copy'); } catch (err) { ok = false; }
74	      document.body.removeChild(area);
75	      ok ? resolve() : reject(new Error('copy failed'));
76	    });
77	  }
78	
79	  function copyable(root) {
80	    var scope = root || document;
81	    var buttons = scope.querySelectorAll('.copy-btn[data-copy-target]');
82	    Array.prototype.forEach.call(buttons, function (btn) {
83	      if (btn.dataset.copyWired === 'true') return;
84	      btn.dataset.copyWired = 'true';
85	      var original = btn.textContent;
86	      btn.addEventListener('click', function () {
87	        var target = document.getElementById(btn.getAttribute('data-copy-target'));
88	        if (!target) return;
89	        copyText(target.textContent).then(function () {
90	          btn.textContent = 'Copied';
91	          btn.classList.add('is-copied');
92	        }, function () {
93	          btn.textContent = 'Press Ctrl+C';
94	          btn.classList.add('is-copied');
95	        });
96	        window.setTimeout(function () {
97	          btn.textContent = original;
98	          btn.classList.remove('is-copied');
99	        }, 1800);
100	      });
101	    });
102	  }
103	
104	  /* ---------- boot ---------- */
105	
106	  window.CS101 = { esc: esc, el: el, copyable: copyable };
107	
108	  document.addEventListener('DOMContentLoaded', function () {
109	    initNav();
110	    copyable(document);
111	  });
112	})();
113

1	@charset "utf-8";
2	
3	/* ============================================================================
4	   CS 101: Introduction to Computer Science — site stylesheet
5	   Fall 2026 · single file, no build step, no framework, no @import,
6	   no webfonts, no external URLs of any kind.
7	
8	   Contents
9	     1.  Tokens (light palette + geometry + type)
10	     2.  Tokens (dark palette override — colour tokens only)
11	     3.  Reset & base elements
12	     4.  Accessibility utilities (skip link, focus, reduced motion)
13	     5.  Layout (.wrap, .section, .stack, grids)
14	     6.  Header, brand & navigation
15	     7.  Page head, hero & typography helpers
16	     8.  Cards
17	     9.  Callouts
18	     10. Badges
19	     11. Buttons & filter bar
20	     12. Tables
21	     13. Code blocks
22	     14. Definition grid (.dl-grid)
23	     15. Schedule weeks
24	     16. Assignments
25	     17. Contact
26	     18. Empty state
27	     19. Footer
28	     20. Print
29	   ==========================================================================*/
30	
31	
32	/* ============================================================================
33	   1. TOKENS — light palette (the default, defined on bare :root)
34	   ----------------------------------------------------------------------------
35	   Contrast intent (WCAG, ratios measured against the surface each value is
36	   actually painted on):
37	     --text        #1b1d24 on --surface #ffffff  ≈ 16.1:1   (body copy)
38	     --text        #1b1d24 on --bg      #f6f7fb  ≈ 15.1:1
39	     --text-muted  #555b6b on --surface #ffffff  ≈  6.9:1   (still > 4.5:1 so
40	                   muted text is never a contrast trap)
41	     --accent      #4338ca on --surface #ffffff  ≈  8.3:1   (links, large text)
42	     --accent-contrast #ffffff on --accent       ≈  8.3:1   (button labels)
43	     --ok          #146c3a on #ffffff            ≈  5.6:1
44	     --warn        #8a5300 on #ffffff            ≈  5.9:1
45	     --danger      #b42318 on #ffffff            ≈  5.9:1
46	     --border      #8c92a3 on #ffffff            ≈  3.1:1   (>= 3:1, used for
47	                   control outlines, table rules and any border that carries
48	                   meaning — i.e. real UI boundaries)
49	     --border-subtle is decorative only (hairline separators inside an already
50	                   bounded surface); it never carries information on its own,
51	                   so the 3:1 UI rule does not apply to it.
52	   ==========================================================================*/
53	
54	:root {
55	  /* -- surfaces ------------------------------------------------------------ */
56	  --bg: #f6f7fb;             /* page canvas: a barely-there cool grey        */
57	  --surface: #ffffff;        /* cards, header, code blocks                   */
58	  --surface-2: #eceff6;      /* inset strips: code heads, table headers      */
59	
60	  /* -- ink ----------------------------------------------------------------- */
61	  --text: #1b1d24;
62	  --text-muted: #555b6b;
63	
64	  /* -- lines --------------------------------------------------------------- */
65	  --border: #8c92a3;         /* >= 3:1 — real UI boundaries                   */
66	  --border-subtle: #dfe3ec;  /* decorative hairlines inside a bounded surface */
67	
68	  /* -- accent (single indigo, used sparingly) ------------------------------ */
69	  --accent: #4338ca;
70	  --accent-contrast: #ffffff;
71	  --accent-soft: #ecebff;    /* tinted fill behind accent content            */
72	
73	  /* -- status -------------------------------------------------------------- */
74	  --ok: #146c3a;
75	  --ok-soft: #e6f5ec;
76	  --warn: #8a5300;
77	  --warn-soft: #fdf1de;
78	  --danger: #b42318;
79	  --danger-soft: #fdecea;
80	
81	  /* -- geometry ------------------------------------------------------------ */
82	  --radius: 0.625rem;
83	  --radius-sm: 0.375rem;
84	  --radius-pill: 999px;
85	  --shadow: 0 1px 2px rgba(20, 24, 40, 0.06),
86	            0 6px 20px -12px rgba(20, 24, 40, 0.28);
87	  --shadow-sm: 0 1px 2px rgba(20, 24, 40, 0.08);
88	
89	  /* -- type (system stacks only) ------------------------------------------ */
90	  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue",
91	          Arial, "Noto Sans", sans-serif;
92	  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas,
93	          "Liberation Mono", "Courier New", monospace;
94	
95	  /* -- rhythm -------------------------------------------------------------- */
96	  --measure: 65ch;           /* comfortable reading width for prose          */
97	  --wrap: 68rem;
98	  --gap: 1.25rem;
99	  --space-section: 3rem;
100	
101	  /* -- print ink (referenced only from the print block) -------------------- */
102	  --print-ink: #000000;
103	  --print-paper: #ffffff;
104	}
105	
106	
107	/* ============================================================================
108	   2. TOKENS — dark palette
109	   ----------------------------------------------------------------------------
110	   Only colour tokens are overridden; geometry and type stay identical.
111	   Contrast intent:
112	     --text        #e7e9f2 on --surface #171a22  ≈ 13.7:1
113	     --text-muted  #a6accd? -> #a7adc0 on #171a22 ≈  7.6:1
114	     --accent      #a9b6ff on #171a22            ≈  9.0:1  (light indigo keeps
115	                   the same "single accent" identity without glowing)
116	     --accent-contrast #101320 on --accent       ≈  9.0:1
117	     --ok          #4ade80 on #171a22            ≈ 10.2:1
118	     --warn        #f5b73d on #171a22            ≈  9.7:1
119	     --danger      #ff9c94 on #171a22            ≈  8.1:1
120	     --border      #5a6178 on #171a22            ≈  3.2:1  (>= 3:1)
121	   ==========================================================================*/
122	
123	@media (prefers-color-scheme: dark) {
124	  :root {
125	    --bg: #0e1016;
126	    --surface: #171a22;
127	    --surface-2: #1f232e;
128	
129	    --text: #e7e9f2;
130	    --text-muted: #a7adc0;
131	
132	    --border: #5a6178;
133	    --border-subtle: #2b303d;
134	
135	    --accent: #a9b6ff;
136	    --accent-contrast: #101320;
137	    --accent-soft: #232741;
138	
139	    --ok: #4ade80;
140	    --ok-soft: #14291d;
141	    --warn: #f5b73d;
142	    --warn-soft: #2e2412;
143	    --danger: #ff9c94;
144	    --danger-soft: #331a18;
145	
146	    --shadow: 0 1px 2px rgba(0, 0, 0, 0.5),
147	              0 8px 24px -14px rgba(0, 0, 0, 0.8);
148	    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.5);
149	  }
150	}
151	
152	
153	/* ============================================================================
154	   3. RESET & BASE
155	   ==========================================================================*/
156	
157	*,
158	*::before,
159	*::after { box-sizing: border-box; }
160	
161	html {
162	  -webkit-text-size-adjust: 100%;
163	  scroll-behavior: smooth;
164	  scroll-padding-top: 5rem;   /* sticky header must not cover #anchors */
165	}
166	
167	body {
168	  margin: 0;
169	  background: var(--bg);
170	  color: var(--text);
171	  font-family: var(--font);
172	  font-size: 1rem;
173	  line-height: 1.65;
174	  /* Nothing may ever push the page sideways — wide content scrolls inside
175	     .table-wrap / pre instead. */
176	  overflow-x: hidden;
177	  overflow-wrap: break-word;
178	  word-break: normal;
179	  -webkit-font-smoothing: antialiased;
180	  text-rendering: optimizeLegibility;
181	}
182	
183	h1, h2, h3, h4, h5, h6 {
184	  margin: 0 0 0.5em;
185	  line-height: 1.2;
186	  font-weight: 650;
187	  letter-spacing: -0.01em;
188	  text-wrap: balance;
189	}
190	
191	h1 { font-size: clamp(1.75rem, 1.35rem + 2vw, 2.5rem); }
192	h2 { font-size: clamp(1.35rem, 1.15rem + 1vw, 1.75rem); }
193	h3 { font-size: 1.15rem; }
194	h4 { font-size: 1rem; }
195	
196	p, ul, ol, dl, figure, blockquote, table { margin: 0 0 1rem; }
197	p:last-child, ul:last-child, ol:last-child, dl:last-child { margin-bottom: 0; }
198	
199	/* Comfortable measure for running prose. Grid/flex children inherit a
200	   narrower box anyway, so this only ever tightens, never overflows. */
201	main p,
202	main li,
203	main dd,
204	main blockquote { max-width: var(--measure); }
205	
206	ul, ol { padding-left: 1.35rem; }
207	li + li { margin-top: 0.25rem; }
208	
209	a {
210	  color: var(--accent);
211	  text-decoration: underline;
212	  text-underline-offset: 0.15em;
213	  text-decoration-thickness: from-font;
214	  /* Long URLs must never widen the page. */
215	  overflow-wrap: anywhere;
216	}
217	a:hover { text-decoration-thickness: 2px; }
218	
219	strong, b { font-weight: 650; }
220	
221	hr {
222	  border: 0;
223	  border-top: 1px solid var(--border-subtle);
224	  margin: 2rem 0;
225	}
226	
227	img, svg, video, canvas, iframe {
228	  max-width: 100%;
229	  height: auto;
230	  display: block;
231	}
232	
233	blockquote {
234	  margin-inline: 0;
235	  padding: 0.25rem 0 0.25rem 1rem;
236	  border-left: 3px solid var(--border);
237	  color: var(--text-muted);
238	}
239	
240	/* Inline code (block-level code is handled in §13). */
241	code, kbd, samp {
242	  font-family: var(--mono);
243	  font-size: 0.9em;
244	}
245	
246	:not(pre) > code {
247	  background: var(--surface-2);
248	  border: 1px solid var(--border-subtle);
249	  border-radius: var(--radius-sm);
250	  padding: 0.1em 0.35em;
251	  overflow-wrap: anywhere;
252	}
253	
254	button, input, select, textarea {
255	  font: inherit;
256	  color: inherit;
257	}
258	
259	::selection {
260	  background: var(--accent);
261	  color: var(--accent-contrast);
262	}
263	
264	
265	/* ============================================================================
266	   4. ACCESSIBILITY UTILITIES
267	   ==========================================================================*/
268	
269	/* Skip link: off-screen but focusable, then pinned top-left when focused. */
270	.skip-link {
271	  position: absolute;
272	  top: 0;
273	  left: 0;
274	  z-index: 100;
275	  transform: translateY(-150%);
276	  margin: 0.5rem;
277	  padding: 0.6rem 1rem;
278	  background: var(--accent);
279	  color: var(--accent-contrast);
280	  border-radius: var(--radius-sm);
281	  box-shadow: var(--shadow);
282	  text-decoration: none;
283	  font-weight: 600;
284	}
285	
286	.skip-link:focus,
287	.skip-link:focus-visible {
288	  transform: translateY(0);
289	  outline: 2px solid var(--accent);
290	  outline-offset: 2px;
291	}
292	
293	/* One visible focus treatment for the whole site. Nothing anywhere in this
294	   file removes an outline without providing a replacement. */
295	:focus-visible {
296	  outline: 2px solid var(--accent);
297	  outline-offset: 2px;
298	  border-radius: var(--radius-sm);
299	}
300	
301	/* Browsers that support :focus-visible get the refined behaviour; the default
302	   focus ring is kept for everything else. */
303	:is(a, button, input, select, textarea, summary, [tabindex]):focus:not(:focus-visible) {
304	  outline: none;
305	}
306	
307	#main:focus { outline: none; }
308	
309	@media (prefers-reduced-motion: reduce) {
310	  html { scroll-behavior: auto; }
311	  *,
312	  *::before,
313	  *::after {
314	    animation-duration: 0.001ms !important;
315	    animation-iteration-count: 1 !important;
316	    transition-duration: 0.001ms !important;
317	    scroll-behavior: auto !important;
318	  }
319	}
320	
321	
322	/* ============================================================================
323	   5. LAYOUT
324	   ==========================================================================*/
325	
326	.wrap {
327	  width: 100%;
328	  max-width: var(--wrap);
329	  margin-inline: auto;
330	  padding-inline: 1.125rem;
331	}
332	
333	@media (min-width: 48rem) {
334	  .wrap { padding-inline: 2rem; }
335	}
336	
337	.section {
338	  padding-block: 2.25rem;
339	}
340	
341	@media (min-width: 48rem) {
342	  .section { padding-block: var(--space-section); }
343	}
344	
345	.section + .section { padding-top: 0; }
346	
347	/* Vertical flow: consistent gap between siblings without margin collapse. */
348	.stack > * + * { margin-top: var(--gap); }
349	.stack--tight > * + * { margin-top: 0.5rem; }
350	
351	/* Card grids. auto-fit + minmax(min(100%, N)) collapses to a single column on
352	   narrow screens without needing a breakpoint, and never overflows at 320px. */
353	.grid {
354	  display: grid;
355	  gap: var(--gap);
356	  align-items: start;
357	}
358	
359	.grid-2 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr)); }
360	.grid-3 { grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); }
361	
362	/* Belt and braces: force one column below 40rem as the spec requires. */
363	@media (max-width: 39.999rem) {
364	  .grid-2,
365	  .grid-3 { grid-template-columns: 1fr; }
366	}
367	
368	
369	/* ============================================================================
370	   6. HEADER, BRAND & NAVIGATION
371	   ==========================================================================*/
372	
373	.site-header {
374	  position: sticky;
375	  top: 0;
376	  z-index: 50;
377	  background: var(--surface);
378	  border-bottom: 1px solid var(--border-subtle);
379	  box-shadow: var(--shadow-sm);
380	}
381	
382	.header-inner {
383	  display: flex;
384	  flex-wrap: wrap;
385	  align-items: center;
386	  justify-content: space-between;
387	  gap: 0.75rem;
388	  padding-block: 0.75rem;
389	}
390	
391	/* -- brand ---------------------------------------------------------------- */
392	
393	.brand {
394	  display: inline-flex;
395	  align-items: baseline;
396	  flex-wrap: wrap;
397	  gap: 0.5rem;
398	  text-decoration: none;
399	  color: var(--text);
400	  min-width: 0;
401	}
402	
403	.brand:hover .brand-name { color: var(--text); }
404	
405	.brand-code {
406	  font-weight: 700;
407	  letter-spacing: 0.02em;
408	  color: var(--accent);
409	  font-size: 1.0625rem;
410	}
411	
412	.brand-name {
413	  color: var(--text-muted);
414	  font-size: 0.9375rem;
415	}
416	
417	/* Keep the header compact on the very smallest screens. */
418	@media (max-width: 26.25rem) {
419	  .brand-name { display: none; }
420	}
421	
422	/* -- toggle (mobile only) -------------------------------------------------- */
423	
424	.nav-toggle {
425	  display: inline-flex;
426	  align-items: center;
427	  gap: 0.5rem;
428	  padding: 0.45rem 0.7rem;
429	  background: var(--surface);
430	  color: var(--text);
431	  border: 1px solid var(--border);
432	  border-radius: var(--radius-sm);
433	  cursor: pointer;
434	  transition: background-color 150ms ease, border-color 150ms ease;
435	}
436	
437	.nav-toggle:hover { background: var(--surface-2); }
438	
439	.nav-toggle-label {
440	  font-size: 0.875rem;
441	  font-weight: 600;
442	}
443	
444	/* Three bars drawn with currentColor, so they follow the token palette. */
445	.nav-toggle-bars {
446	  position: relative;
447	  display: block;
448	  width: 1.125rem;
449	  height: 2px;
450	  background: currentColor;
451	  border-radius: 2px;
452	}
453	
454	.nav-toggle-bars::before,
455	.nav-toggle-bars::after {
456	  content: "";
457	  position: absolute;
458	  left: 0;
459	  width: 100%;
460	  height: 2px;
461	  background: currentColor;
462	  border-radius: 2px;
463	}
464	
465	.nav-toggle-bars::before { top: -0.3125rem; }
466	.nav-toggle-bars::after { top: 0.3125rem; }
467	
468	.nav-toggle[aria-expanded="true"] {
469	  background: var(--accent-soft);
470	  border-color: var(--accent);
471	}
472	
473	/* -- nav ------------------------------------------------------------------- */
474	
475	.site-nav ul {
476	  list-style: none;
477	  margin: 0;
478	  padding: 0;
479	  display: flex;
480	  flex-direction: column;
481	  gap: 0.125rem;
482	}
483	
484	.site-nav li + li { margin-top: 0; }
485	
486	.site-nav a {
487	  display: block;
488	  padding: 0.6rem 0.5rem;
489	  border-radius: var(--radius-sm);
490	  color: var(--text);
491	  text-decoration: none;
492	  font-weight: 500;
493	}
494	
495	.site-nav a:hover {
496	  background: var(--surface-2);
497	  color: var(--accent);
498	}
499	
500	/* Current page is marked by weight + a solid underline rule, not colour
501	   alone, so it survives greyscale, dark mode and colour-blind viewing. */
502	.site-nav a[aria-current="page"] {
503	  color: var(--accent);
504	  font-weight: 700;
505	  text-decoration: underline;
506	  text-decoration-thickness: 2px;
507	  text-underline-offset: 0.3em;
508	}
509	
510	/* Mobile: hidden until .is-open, then a full-width stack under the header. */
511	@media (max-width: 47.999rem) {
512	  .site-nav {
513	    display: none;
514	    flex-basis: 100%;
515	    width: 100%;
516	  }
517	
518	  .site-nav.is-open {
519	    display: block;
520	    border-top: 1px solid var(--border-subtle);
521	    padding-block: 0.5rem 0.75rem;
522	    margin-top: 0.25rem;
523	  }
524	
525	  .site-nav.is-open a { padding-inline: 0.75rem; }
526	
527	  .site-nav.is-open a[aria-current="page"] {
528	    background: var(--accent-soft);
529	  }
530	}
531	
532	/* Desktop: horizontal row, no toggle. */
533	@media (min-width: 48rem) {
534	  .nav-toggle { display: none; }
535	
536	  .site-nav {
537	    display: block;
538	    flex-basis: auto;
539	    width: auto;
540	  }
541	
542	  .site-nav ul {
543	    flex-direction: row;
544	    align-items: center;
545	    gap: 0.25rem;
546	  }
547	
548	  .site-nav a { padding: 0.4rem 0.7rem; }
549	}
550	
551	
552	/* ============================================================================
553	   7. PAGE HEAD, HERO & TYPOGRAPHY HELPERS
554	   ==========================================================================*/
555	
556	.page-head {
557	  background: var(--surface);
558	  border-bottom: 1px solid var(--border-subtle);
559	  padding-block: 2rem 1.75rem;
560	  margin-bottom: 2rem;
561	}
562	
563	.page-head h1 { margin-bottom: 0.35rem; }
564	
565	.eyebrow {
566	  margin: 0 0 0.35rem;
567	  font-size: 0.8125rem;
568	  font-weight: 700;
569	  letter-spacing: 0.09em;
570	  text-transform: uppercase;
571	  color: var(--accent);
572	}
573	
574	.lede {
575	  font-size: 1.0625rem;
576	  line-height: 1.6;
577	  color: var(--text-muted);
578	  max-width: var(--measure);
579	}
580	
581	@media (min-width: 48rem) {
582	  .lede { font-size: 1.15rem; }
583	}
584	
585	.muted {
586	  color: var(--text-muted);
587	  font-size: 0.9375rem;
588	}
589	
590	/* -- hero (home page) ------------------------------------------------------ */
591	
592	.hero {
593	  background: var(--surface);
594	  border-bottom: 1px solid var(--border-subtle);
595	  padding-block: 2.5rem 2.25rem;
596	}
597	
598	@media (min-width: 48rem) {
599	  .hero { padding-block: 4rem 3.5rem; }
600	}
601	
602	.hero h1 { max-width: 20ch; }
603	.hero .lede { max-width: 60ch; }
604	
605	.hero-actions {
606	  display: flex;
607	  flex-wrap: wrap;
608	  gap: 0.75rem;
609	  margin-top: 1.5rem;
610	}
611	
612	
613	/* ============================================================================
614	   8. CARDS
615	   ==========================================================================*/
616	
617	.card {
618	  background: var(--surface);
619	  border: 1px solid var(--border-subtle);
620	  border-radius: var(--radius);
621	  box-shadow: var(--shadow-sm);
622	  padding: 1.25rem;
623	  height: 100%;
624	}
625	
626	@media (min-width: 48rem) {
627	  .card { padding: 1.5rem; }
628	}
629	
630	.card > :first-child { margin-top: 0; }
631	.card > :last-child { margin-bottom: 0; }
632	
633	.card h2 {
634	  font-size: 1.25rem;
635	  margin-bottom: 0.4rem;
636	}
637	
638	.card h3 {
639	  font-size: 1.0625rem;
640	  margin-bottom: 0.35rem;
641	}
642	
643	.card-title {
644	  margin: 0 0 0.35rem;
645	  font-size: 1.125rem;
646	  font-weight: 650;
647	  line-height: 1.3;
648	}
649	
650	.card-meta {
651	  margin: 0 0 0.75rem;
652	  font-size: 0.875rem;
653	  color: var(--text-muted);
654	  display: flex;
655	  flex-wrap: wrap;
656	  align-items: center;
657	  gap: 0.5rem;
658	}
659	
660	
661	/* ============================================================================
662	   9. CALLOUTS
663	   ==========================================================================*/
664	
665	.callout {
666	  border: 1px solid var(--border);
667	  border-left: 4px solid var(--border);
668	  border-radius: var(--radius);
669	  background: var(--surface);
670	  padding: 1rem 1.125rem;
671	  margin-block: 1.25rem;
672	}
673	
674	.callout > :first-child { margin-top: 0; }
