959	
960	pre {
961	  overflow-x: auto;            /* code scrolls inside its own box */
962	  -webkit-overflow-scrolling: touch;
963	  max-width: 100%;
964	  background: var(--surface);
965	  border-radius: var(--radius);
966	  margin-block: 1.25rem;
967	  padding: 0.875rem 1rem;
