    /* ---- lab 12

1	/* CS 101 — assignments page renderer.
2	   Reads window.ASSIGNMENTS (see data/assignments.js) and builds the list.
3	   Plain script, no modules, no dependencies beyond the CS101 helpers in
4	   assets/site.js. Every value that comes out of the data file is escaped
5	   with CS101.esc before it reaches the page. */
6	(function () {
7	  'use strict';
8	
9	  var CS101 = window.CS101 || {};
10	  // The fallback must be a real escaper: if site.js ever fails to load, an
11	  // identity function here would push raw code samples into innerHTML.
12	  var esc = CS101.esc || function (value) {
13	    return String(value == null ? '' : value)
14	      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
15	      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
16	  };
17	
18	  var TYPE_LABELS = { ps: 'Problem set', lab: 'Lab', project: 'Project' };
19	  var STATUS_LABELS = { open: 'Open', closed: 'Closed', upcoming: 'Upcoming' };
20	
21	  var FILTERS = [
22	    { key: 'all', label: 'All' },
23	    { key: 'ps', label: 'Problem sets' },
24	    { key: 'lab', label: 'Labs' },
25	    { key: 'project', label: 'Project' }
26	  ];
27	
28	  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
29	                'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
30	  var DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
31	
32	  /* ---------- small helpers ---------- */
33	
34	  // "2026-09-04" -> "Fri 4 Sep 2026". Parsed by hand so the browser's
35	  // timezone can never shift the date by a day.
36	  function formatDate(value) {
37	    var text = String(value == null ? '' : value).trim();
38	    var parts = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
39	    if (!parts) return text;
40	    var year = Number(parts[1]);
41	    var month = Number(parts[2]) - 1;
42	    var day = Number(parts[3]);
43	    if (month < 0 || month > 11) return text;
44	    var date = new Date(Date.UTC(year, month, day));
45	    // Date.UTC rolls impossible dates over silently ("2026-09-31" becomes
46	    // 1 Oct), which would print a real-looking date with the wrong weekday.
47	    // Show the raw text instead so the typo is visible in the data file.
48	    if (date.getUTCDate() !== day || date.getUTCMonth() !== month) return text;
49	    return DAYS[date.getUTCDay()] + ' ' + day + ' ' + MONTHS[month] + ' ' + year;
50	  }
51	
52	  function list(value) {
53	    return Object.prototype.toString.call(value) === '[object Array]' ? value : [];
54	  }
55	
56	  function typeLabel(type) {
57	    return TYPE_LABELS[type] || 'Assignment';
58	  }
59	
60	  /* ---------- code blocks ---------- */
61	
62	  // Matches the site's code-block contract exactly. `id` must be unique on
63	  // the page; the Copy button finds its <code> through data-copy-target.
64	  function codeBlock(id, lang, code) {
65	    var body = String(code == null ? '' : code).replace(/^\n+/, '').replace(/\s+$/, '');
66	    return '' +
67	      '<div class="code-block">' +
68	        '<div class="code-head">' +
69	          '<span class="code-lang">' + esc(lang || 'Python') + '</span>' +
70	          '<button class="copy-btn" data-copy-target="' + esc(id) + '">Copy</button>' +
71	        '</div>' +
72	        '<pre><code id="' + esc(id) + '">' + esc(body) + '</code></pre>' +
73	      '</div>';
74	  }
75	
76	  /* ---------- one assignment ---------- */
77	
78	  function renderItem(item) {
79	    var id = String(item.id == null ? '' : item.id);
80	    var type = String(item.type == null ? '' : item.type);
81	    var status = String(item.status == null ? '' : item.status);
82	    var html = [];
83	
84	    html.push('<article class="assignment" id="' + esc(id) + '" data-type="' + esc(type) + '">');
85	
86	    /* --- head --- */
87	    html.push('<div class="assignment-head">');
88	    html.push('<p><span class="badge">' + esc(typeLabel(type)) + '</span> ' +
89	              '<span class="badge badge-due">Due ' + esc(formatDate(item.due)) + '</span></p>');
90	    html.push('<h2 class="card-title">' + esc(item.title) + '</h2>');
91	    html.push('<p class="card-meta">' +
92	              esc(item.points) + ' points · Posted ' + esc(formatDate(item.posted)) +
93	              ' · Week ' + esc(item.week) +
94	              ' · ' + esc(STATUS_LABELS[status] || status) +
95	              '</p>');
96	    html.push('</div>');
97	
98	    /* --- body --- */
99	    html.push('<div class="assignment-body">');
100	
101	    if (item.summary) {
102	      html.push('<p class="lede">' + esc(item.summary) + '</p>');
103	    }
104	
105	    var objectives = list(item.objectives);
106	    if (objectives.length) {
107	      html.push('<h3>What you will practise</h3><ul>');
108	      objectives.forEach(function (line) {
109	        html.push('<li>' + esc(line) + '</li>');
110	      });
111	      html.push('</ul>');
112	    }
113	
114	    var tasks = list(item.tasks);
115	    if (tasks.length) {
116	      html.push('<h3>What to do</h3><ol>');
117	      tasks.forEach(function (line) {
118	        html.push('<li>' + esc(line) + '</li>');
119	      });
120	      html.push('</ol>');
121	    }
122	
123	    if (item.starter && item.starter.code) {
124	      html.push('<h3>Starter file</h3>');
125	      html.push('<p class="muted">Save this as <code>' + esc(item.starter.filename || 'starter.py') +
126	                '</code>, then work through the TODO comments.</p>');
127	      html.push(codeBlock('code-' + id + '-starter', item.starter.lang, item.starter.code));
128	    }
129	
130	    var examples = list(item.examples);
131	    if (examples.length) {
132	      html.push('<h3>Worked example' + (examples.length > 1 ? 's' : '') + '</h3>');
133	      examples.forEach(function (example, index) {
134	        html.push('<p class="card-title">' + esc(example.title) + '</p>');
135	        if (example.note) {
136	          html.push('<div class="callout callout-info"><p>' + esc(example.note) + '</p></div>');
137	        }
138	        html.push(codeBlock('code-' + id + '-ex' + (index + 1), example.lang, example.code));
139	      });
140	    }
141	
142	    if (item.submit) {
143	      html.push('<h3>How to hand it in</h3>');
144	      html.push('<div class="callout callout-ok"><p>' + esc(item.submit) + '</p></div>');
145	    }
146	
147	    var rubric = list(item.rubric);
148	    if (rubric.length) {
149	      var total = 0;
150	      html.push('<h3>Marking</h3>');
151	      html.push('<div class="table-wrap"><table class="data-table">');
152	      html.push('<caption class="muted">Rubric for ' + esc(item.title) + '</caption>');
153	      html.push('<thead><tr><th scope="col">Criterion</th><th scope="col">Points</th></tr></thead>');
154	      html.push('<tbody>');
155	      rubric.forEach(function (row) {
156	        total += Number(row && row.points) || 0;
157	        html.push('<tr><td>' + esc(row && row.criterion) + '</td><td>' + esc(row && row.points) + '</td></tr>');
158	      });
159	      html.push('</tbody>');
160	      html.push('<tfoot><tr><th scope="row">Total</th><td>' + esc(total) + '</td></tr></tfoot>');
161	      html.push('</table></div>');
162	    }
163	
164	    html.push('</div>');   // .assignment-body
165	    html.push('</article>');
166	
167	    return html.join('');
168	  }
169	
170	  /* ---------- page wiring ---------- */
171	
172	  function init() {
173	    var listNode = document.getElementById('assignment-list');
174	    var filterNode = document.getElementById('assignment-filters');
175	    if (!listNode) return;
176	
177	    var data = window.ASSIGNMENTS;
178	    var items = data && list(data.items).filter(function (item) {
179	      return item && item.id;
180	    });
181	
182	    if (!items || !items.length) {
183	      listNode.innerHTML = '<p class="empty">No assignments have been posted yet. ' +
184	        'Check back after the first lecture.</p>';
185	      if (filterNode) filterNode.innerHTML = '';
186	      return;
187	    }
188	
189	    // Build the filter bar from FILTERS so the markup and the behaviour
190	    // can never drift apart.
191	    if (filterNode) {
192	      var bar = ['<div class="filter-bar" role="group" aria-label="Filter assignments">'];
193	      FILTERS.forEach(function (filter) {
194	        bar.push('<button type="button" class="filter-btn" data-filter="' + filter.key +
195	                 '" aria-pressed="' + (filter.key === 'all' ? 'true' : 'false') + '">' +
196	                 filter.label + '</button>');
197	      });
198	      bar.push('</div>');
199	      filterNode.innerHTML = bar.join('');
200	    }
201	
202	    var body = items.map(renderItem).join('');
203	    listNode.innerHTML = body + '<p class="empty" id="assignment-empty" hidden>' +
204	      'No assignments of that kind yet.</p>';
205	
206	    // The copy buttons only exist now that the HTML has been injected.
207	    if (typeof CS101.copyable === 'function') CS101.copyable(listNode);
208	
209	    var articles = listNode.querySelectorAll('.assignment');
210	    var emptyNote = document.getElementById('assignment-empty');
211	    var buttons = filterNode ? filterNode.querySelectorAll('.filter-btn') : [];
212	
213	    function applyFilter(key) {
214	      var shown = 0;
215	      Array.prototype.forEach.call(articles, function (article) {
216	        var match = key === 'all' || article.getAttribute('data-type') === key;
217	        article.hidden = !match;
218	        if (match) shown += 1;
219	      });
220	      if (emptyNote) emptyNote.hidden = shown !== 0;
221	      Array.prototype.forEach.call(buttons, function (button) {
222	        button.setAttribute('aria-pressed',
223	          button.getAttribute('data-filter') === key ? 'true' : 'false');
224	      });
225	    }
226	
227	    Array.prototype.forEach.call(buttons, function (button) {
228	      button.addEventListener('click', function () {
229	        applyFilter(button.getAttribute('data-filter'));
230	      });
231	    });
232	
233	    applyFilter('all');
234	
235	    // Deep links from the schedule page look like assignments.html#ps3.
236	    // Clear any filter first so the target is definitely visible, then scroll.
237	    function goToHash() {
238	      var raw = String(window.location.hash || '').replace(/^#/, '');
239	      // A malformed escape (e.g. "#50%") makes decodeURIComponent throw, which
240	      // would otherwise abort init() before the hashchange listener is added.
241	      var wanted;
242	      try {
243	        wanted = decodeURIComponent(raw);
244	      } catch (err) {
245	        wanted = raw;
246	      }
247	      if (!wanted) return;
248	      var target = document.getElementById(wanted);
249	      if (!target || !target.classList.contains('assignment')) return;
250	      applyFilter('all');
251	      target.scrollIntoView();
252	    }
253	
254	    goToHash();
255	    window.addEventListener('hashchange', goToHash);
256	  }
257	
258	  if (document.readyState === 'loading') {
259	    document.addEventListener('DOMContentLoaded', init);
260	  } else {
261	    init();
262	  }
263	})();
